"""検査 b (文書のリンクとアンカー)。

ドメインのディレクトリの下の手書きの Markdown について、次のことを検査する。形式の SSOT はプラグインの規則の文書
(ファイル doc-structured/rules/doc-structured-docs.md)。
  - 手書きのファイルの名前と場所 (モジュール documents が報告する)
  - 先頭のファイルの ID のアンカーと、その次の「#」の見出し
  - 節のアンカーの ID の形 (<ファイルの ID>-h-<名前>) と、その次の「##」から「######」の見出し。アンカーを付けた見出しにリンクが無い
  - 同じ ID のアンカーが 2 つ無い
  - リンクを reference-style ([ラベル]・[文][ラベル]) だけで書く ([文](URL)・<URL>・文中の URL・[ラベル][] が無い)
  - 定義の無いラベル・使われていない定義の行・同じラベルの定義の行が無い
  - 定義の行を末尾のまとまりに書き、段落の一部になっていない
  - 定義の行の href が、ID の形で、参照先のアンカーのあるファイルを指し、title が参照先の完全な名前と同じ
    (外部の URL の定義の行は、title を検査しない)
画像は規則の対象にしないので、本文のリンクで使われず、reference-style の画像だけが使うラベルの定義の行は、
href・title・使われていないことを検査しない。
"""

import posixpath
from dataclasses import dataclass

from . import markdown, names
from .documents import HandwrittenFile, Index, Target, section_name
from .names import IdError
from .problems import Problem

EXTERNAL_PREFIXES = ("http://", "https://")


def is_external(destination: str) -> bool:
    return strip_angle(destination).startswith(EXTERNAL_PREFIXES)


def strip_angle(destination: str) -> str:
    if destination.startswith("<") and destination.endswith(">"):
        return destination[1:-1]
    return destination


@dataclass(frozen=True)
class Resolved:
    """内部の定義の行の参照先。target が None なら、message が誤りの説明。

    by_id は、href の ID の参照先はあるがパスだけが違うときの、その参照先 (直し方が 1 つに決まる)。
    """

    target: Target | None
    message: str = ""
    by_id: Target | None = None


def resolve(handwritten: HandwrittenFile, definition: markdown.Definition, index: Index) -> Resolved:
    """内部の定義の行 (外部の URL でないもの) の href から、参照先を求める。"""
    destination = strip_angle(definition.destination)
    path, sep, fragment = destination.partition("#")
    if not sep or not fragment:
        return Resolved(None, f"href {destination} が ID のアンカー (#<ID>) を指していない")
    try:
        names.parse_id(fragment)
    except IdError as e:
        return Resolved(None, f"href の ID の形が違う: {e}")
    target = index.targets.get(fragment)
    if target is None:
        return Resolved(None, f"href の参照先 {fragment} のアンカーが無い")
    resolved = handwritten.path if not path else posixpath.normpath(posixpath.join(posixpath.dirname(handwritten.path), path))
    if resolved != target.path:
        return Resolved(
            None,
            f"href が、参照先 {fragment} のアンカーのあるファイルを指していない (正しい href は {target.href(handwritten.path)})",
            by_id=target,
        )
    return Resolved(target)


def definition_line(label: str, target: Target, from_path: str, quote: str = '"') -> str:
    """参照先 target を指す定義の行。"""
    title = markdown.escape_title(target.full_name(), quote)
    return f"[{label}]: {target.href(from_path)} {quote}{title}{markdown.closing_quote(quote)}"


def image_only_labels(document: markdown.Document) -> set[str]:
    """本文のリンクで使われず、reference-style の画像だけが使うラベル (比べる形)。"""
    used = {markdown.normalize_label(r.label) for r in document.references}
    return {markdown.normalize_label(label) for label in document.image_labels} - used


def candidate_text(targets: list[Target]) -> str:
    return "、".join(f"{t.id} ({t.full_name()})" for t in targets)


class _FileChecker:
    def __init__(self, handwritten: HandwrittenFile, index: Index):
        self.file = handwritten
        self.document = handwritten.document
        self.index = index
        self.problems: list[Problem] = []

    def problem(self, message: str, line: int | None = None, column: int | None = None) -> None:
        self.problems.append(Problem("b", self.file.path, message, line, column))

    def check(self) -> list[Problem]:
        self.check_anchors()
        self.check_link_forms()
        self.check_definitions()
        return self.problems

    def check_anchors(self) -> None:
        document = self.document
        file_id = self.file.id
        first = document.first_nonblank()
        file_anchor = next((a for a in document.anchors if a.line == first), None)
        if file_anchor is None:
            self.problem(f'先頭の行に、ファイルの ID のアンカー <a name="{file_id}"></a> が無い', first or 1, 1)
        elif file_anchor.name != file_id:
            self.problem(
                f"先頭のアンカーの ID {file_anchor.name} が、ファイルの ID {file_id} と違う",
                file_anchor.line, file_anchor.column,
            )
        if file_anchor is not None:
            following = document.next_nonblank(file_anchor.line)
            heading = document.heading_at(following) if following else None
            if heading is None or not heading.atx or heading.level != 1:
                self.problem("ファイルの ID のアンカーの次の行に、「#」の見出しが無い", file_anchor.line, file_anchor.column)
        for anchor in document.anchors:
            if anchor is file_anchor:
                continue
            if section_name(file_id, anchor.name) is None:
                self.problem(
                    f"節のアンカーの ID {anchor.name} は、{file_id}-{names.SECTION.symbol}-<名前> の形にする (名前は snake_case)",
                    anchor.line, anchor.column,
                )
                continue
            following = document.next_nonblank(anchor.line)
            heading = document.heading_at(following) if following else None
            if heading is None or not heading.atx or heading.level < 2:
                self.problem("節のアンカーの次の行に、「##」から「######」の見出しが無い", anchor.line, anchor.column)
                continue
            linked = [r for r in document.references if r.line == heading.line]
            linked += [r for r in document.inline_links if r.line == heading.line]
            if linked:
                self.problem(
                    "アンカーを付けた見出しにリンクを書かない (見出しの文は、参照する定義の行の title になるため)",
                    heading.line, linked[0].column,
                )
        for anchor in document.anchors:
            found = self.index.anchors.get(anchor.name, [])
            if len(found) > 1:
                others = [f"{path}:{a.line}" for path, a in found if not (path == self.file.path and a.line == anchor.line)]
                self.problem(f"同じ ID {anchor.name} のアンカーが {'、'.join(others)} にもある", anchor.line, anchor.column)

    def check_link_forms(self) -> None:
        for link in self.document.inline_links:
            self.problem(
                "[文](URL) の形でリンクを書かない。reference-style ([ラベル] か [文][ラベル]) と定義の行で書く",
                link.line, link.column,
            )
        for url in self.document.urls:
            if url.form == "autolink":
                message = f"<{url.url}> の形でリンクを書かない。reference-style ([ラベル] か [文][ラベル]) と定義の行で書く"
            else:
                message = (
                    f"文中に URL {url.url} をそのまま書かない。reference-style ([ラベル] か [文][ラベル]) と定義の行で書く"
                    "。リンクにしないときは、インラインコードにする"
                )
            self.problem(message, url.line, url.column)
        for reference in self.document.references:
            if reference.form == "collapsed":
                self.problem(
                    f"[{reference.text}][] の形で書かない。[{reference.text}] と書く", reference.line, reference.column
                )

    def check_definitions(self) -> None:
        document = self.document
        defined: dict[str, markdown.Definition] = {}
        images = image_only_labels(document)
        previous_in_paragraph = -1
        for definition in document.definitions:
            key = markdown.normalize_label(definition.label)
            where = (definition.line, definition.column)
            if definition.in_paragraph:
                if previous_in_paragraph != definition.line - 1:
                    self.problem("直前の行と同じ段落になり、定義の行として読まれない。前に空行を入れる", *where)
                previous_in_paragraph = definition.line
            elif definition.line <= document.body_end:
                self.problem("定義の行は、ファイルの末尾のまとまりに書く", *where)
            if key in defined:
                self.problem(f"ラベル {definition.label} の定義の行は、{defined[key].line} 行目にもある", *where)
                continue
            defined[key] = definition
            if key not in images:
                self.check_definition_target(definition)
        used: set[str] = set()
        for reference in document.references:
            key = markdown.normalize_label(reference.label)
            used.add(key)
            if reference.form == "collapsed" or key in defined:
                continue
            candidates = self.index.candidates(reference.label)
            if candidates:
                hint = f"。候補: {candidate_text(candidates)}"
            else:
                hint = "。参照先の候補は無い"
            self.problem(f"ラベル {reference.label} の定義の行が無い{hint}", reference.label_line, reference.label_column)
        for key, definition in defined.items():
            if key not in used and key not in images:
                self.problem(f"ラベル {definition.label} の定義の行が、本文で使われていない", definition.line, definition.column)

    def check_definition_target(self, definition: markdown.Definition) -> None:
        if is_external(definition.destination):
            return
        where = (definition.line, definition.column)
        resolved = resolve(self.file, definition, self.index)
        if resolved.target is None:
            self.problem(resolved.message, *where)
            return
        full_name = resolved.target.full_name()
        if definition.title is None:
            self.problem(f"定義の行に title が無い。参照先の完全な名前「{full_name}」を書く", *where)
        elif definition.title_text != full_name:
            self.problem(f"定義の行の title が、参照先の完全な名前「{full_name}」と違う", *where)


def check_links(index: Index) -> list[Problem]:
    """検査 b: 手書きの Markdown のリンクとアンカー (手書きのファイルの名前と場所は、モジュール documents が報告する)。"""
    problems: list[Problem] = []
    for handwritten in index.files:
        problems += _FileChecker(handwritten, index).check()
    return problems
"""ID と、限定付きの名前。

ID は、種類の記号と名前 (snake_case) をハイフンで交互につなぎ、親から子の順に並べたもの
(例 d-loans-m-loan-a-status-v-on_loan)。ファイルの ID は、親の ID にファイルの種類の記号を足したもの
(例 d-loans-models)。ファイルの種類の記号は名前を取らない。
手書きのファイル (concept・design・problem) の下には、節 (記号 h) と子のファイル (記号 f) の ID を作る
(例 d-loans-concept-h-return_deadline・d-push-design-f-device_operations)。子のファイルの下には節だけを作る。

限定付きの名前は、親から順に「種類 + 名前」を「の」でつないだもの。ユーザーレベルの種類は日本語名をかぎ括弧で、
開発レベルの種類は英語名をコードの書式で書く。名前の形の表の SSOT はプラグインの規則の文書
(ファイル doc-structured/rules/doc-structured-docs.md)。このモジュールの表 KINDS と FILE_KINDS が規則の文書の表と
同じであることは、テスト tests/test_rules_docs.py が検査する。
"""

import re
from dataclasses import dataclass

# 名前 (英語名) の形。英小文字で始まり、英小文字・数字を 1 つの「_」で区切る
NAME_RE = re.compile(r"^[a-z][a-z0-9]*(_[a-z0-9]+)*$")


@dataclass(frozen=True)
class Kind:
    """名前を持つ種類。"""

    symbol: str
    label: str  # 種類の名前 (限定付きの名前と文書に書く)
    user_level: bool  # True なら日本語名をかぎ括弧で、False なら英語名をコードの書式で書く
    parents: tuple[str, ...]  # 親になれる種類の記号。空ならいちばん上の種類


# この版のツールが扱う種類。後の sub-issue で種類を足す
KINDS: dict[str, Kind] = {
    k.symbol: k
    for k in (
        Kind("d", "ドメイン", False, ()),
        Kind("m", "モデル", True, ("d",)),
        Kind("a", "属性", True, ("m",)),
        Kind("v", "値", True, ("a",)),
        Kind("ut", "未分類のアプリケーション用語", True, ("d",)),
    )
}

# 生成するファイルの種類の記号と、そのファイル名。親はドメイン
FILE_KINDS: dict[str, str] = {
    "models": "models.md",
    "terms": "terms.md",
    "unclassified_app_terms": "unclassified_app_terms.md",
}
# 手書きのファイルの種類の記号と、そのファイル名。親はドメイン。ドメインの README.md の表に、この順に載せる
HANDWRITTEN_FILE_KINDS: dict[str, str] = {
    "concept": "concept.md",
    "problem": "problem.md",
    "design": "design.md",
}
FILE_KIND_LABEL = "ファイル"

# 手書きのファイルの節。名前は書く人が決める snake_case で、限定付きの名前には見出しの文を書く
SECTION = Kind("h", "節", True, ())
# 手書きのファイルの子のファイル (100 行を超えたファイルを分けた先)。限定付きの名前には、ドメインのディレクトリからのパスを書く
CHILD_FILE_SYMBOL = "f"


class IdError(ValueError):
    """ID の形が違う。メッセージは利用者に見せる文。"""


@dataclass(frozen=True)
class Part:
    """ID の 1 つの部分。name が None なら、ファイルの種類の記号。"""

    symbol: str
    name: str | None


def is_name(text: str) -> bool:
    return bool(NAME_RE.match(text))


def build_id(parts: list[Part]) -> str:
    tokens: list[str] = []
    for part in parts:
        tokens.append(part.symbol)
        if part.name is not None:
            tokens.append(part.name)
    return "-".join(tokens)


def parse_id(text: str) -> list[Part]:
    """ID を部分に分ける。種類の記号・名前の形・親子の組み合わせが違えば IdError。"""
    tokens = text.split("-")
    parts: list[Part] = []
    i = 0
    while i < len(tokens):
        symbol = tokens[i]
        parent = parts[-1].symbol if parts else None
        if symbol in KINDS or symbol in (SECTION.symbol, CHILD_FILE_SYMBOL):
            if symbol in KINDS:
                kind = KINDS[symbol]
                allowed = (parent is None and not kind.parents) or (parent is not None and parent in kind.parents)
            elif symbol == SECTION.symbol:
                allowed = parent in HANDWRITTEN_FILE_KINDS or parent == CHILD_FILE_SYMBOL
            else:
                allowed = parent in HANDWRITTEN_FILE_KINDS
            if not allowed:
                raise IdError(f"ID {text} の {symbol} は、{parent or '先頭'} の後に書けない")
            if i + 1 >= len(tokens):
                raise IdError(f"ID {text} の {symbol} の後に名前が無い")
            name = tokens[i + 1]
            if not is_name(name):
                raise IdError(f"ID {text} の名前 {name} が snake_case でない")
            parts.append(Part(symbol, name))
            i += 2
        elif symbol in FILE_KINDS:
            if parent != "d" or i + 1 != len(tokens):
                raise IdError(f"ID {text} のファイルの種類 {symbol} は、ドメインの直後の最後にだけ書ける")
            parts.append(Part(symbol, None))
            i += 1
        elif symbol in HANDWRITTEN_FILE_KINDS:
            if parent != "d":
                raise IdError(f"ID {text} のファイルの種類 {symbol} は、ドメインの直後にだけ書ける")
            parts.append(Part(symbol, None))
            i += 1
        else:
            raise IdError(f"ID {text} に知らない種類の記号 {symbol} がある")
    if not parts:
        raise IdError(f"ID {text!r} が空")
    return parts


def kind_of(text: str) -> str:
    """ID の最後の種類の記号。"""
    return parse_id(text)[-1].symbol


def format_part(symbol: str, display: str) -> str:
    """「種類 + 名前」の 1 つ。display は、ユーザーレベルなら日本語名、開発レベルなら英語名、ファイルならファイル名、
    子のファイルならドメインのディレクトリからのパス、節なら見出しの文。"""
    if symbol in FILE_KINDS or symbol in HANDWRITTEN_FILE_KINDS or symbol == CHILD_FILE_SYMBOL:
        return f"{FILE_KIND_LABEL} `{display}`"
    if symbol == SECTION.symbol:
        return f"{SECTION.label}「{display}」"
    kind = KINDS[symbol]
    if kind.user_level:
        return f"{kind.label}「{display}」"
    return f"{kind.label} `{display}`"


def join_parts(formatted: list[str]) -> str:
    """「種類 + 名前」を親から順に「の」でつなぐ。コードの書式の後には空白を 1 つ入れる (「ドメイン `loans` のモデル」)。"""
    result = ""
    for i, text in enumerate(formatted):
        if i > 0:
            result += " の" if result.endswith("`") else "の"
        result += text
    return result

"""サブコマンド links-fix (手書きの Markdown の定義の行とファイルのアンカーを直す)。

直し方が 1 通りに決まるものだけを書き換え、判断の要るものは「パス:行:列: メッセージ」の形で報告する。本文の文は変えない。
  - 先頭の行 (空行を除く) がアンカーでなければ、ファイルの ID のアンカーを足す。先頭のアンカーの ID が違うときは、
    書き換えるか残すかの判断が要るので、足さずに報告する
  - 定義の無いラベルのうち、参照先の候補が 1 件のものに、定義の行を足す (本文で最初に使った順に、末尾のまとまりの後ろへ)
  - 定義の行の title が参照先の完全な名前と違えば、書き換える (引用符の種類は変えない。title が無ければ「"」で足す)
  - 使われていない定義の行を消す。ただし、同じファイルに定義の無いラベルが残るときは、消さずに報告する
    (ラベルの書き間違いのことがあるため)
  - 本文の途中の定義の行と、段落の一部になった定義の行を、末尾のまとまりに移す
  - 定義の行の href の ID が参照先にあり、パスだけが違えば、href を正しい値に書き換える
  - 同じラベルの定義の行のうち、参照先が同じものは後の行を消す。参照先が違えば報告する
reference-style の画像だけが使うラベルの定義の行は、画像が規則の対象でないので、消さず書き換えない (末尾のまとまりへは移す)。
判断の要るもの: 参照先の候補が 0 件か複数のラベル・消さなかった使われていない定義の行・参照先の違う同じラベルの定義の行・
href から参照先を求められない、本文で使われている定義の行・ファイルの ID と違う先頭のアンカー。
利用者が選んだ参照先は、Choice (オプション --choose) で受け取り、定義の行の href と title はツールが作る。
"""

from dataclasses import dataclass, field
from pathlib import Path

from . import markdown
from .documents import HandwrittenFile, Index
from .links import candidate_text, definition_line, image_only_labels, is_external, resolve, strip_angle


@dataclass(frozen=True)
class Choice:
    """利用者が選んだ参照先。value は参照先の ID か、外部の URL (http:// か https:// で始まるもの)。"""

    path: str  # リポジトリのルートからの相対パス
    label: str
    value: str


class ChoiceError(ValueError):
    """--choose の値が使えない。メッセージは利用者に見せる文。"""


@dataclass(frozen=True)
class Report:
    """判断の要るもの。"""

    path: str
    line: int
    column: int
    message: str

    def format(self) -> str:
        return f"{self.path}:{self.line}:{self.column}: {self.message}"


@dataclass
class FixResult:
    changed: list[str] = field(default_factory=list)  # 書き換えたファイル
    reports: list[Report] = field(default_factory=list)


def _label_text(label: str) -> str:
    """定義の行に書くラベル。本文のラベルが改行をまたぐときは、空白 1 つにする。"""
    return " ".join(label.split())


def _definition_key(handwritten: HandwrittenFile, definition: markdown.Definition, index: Index) -> str | None:
    """定義の行の参照先を比べる値。外部の URL ならその URL、内部なら参照先の ID。求められなければ None。"""
    if is_external(definition.destination):
        return strip_angle(definition.destination)
    resolved = resolve(handwritten, definition, index)
    target = resolved.target or resolved.by_id
    return target.id if target else None


def _choice_line(choice: Choice, label: str, handwritten: HandwrittenFile, index: Index) -> str:
    if choice.value.startswith(("http://", "https://")):
        return f"[{label}]: {choice.value}"
    target = index.targets.get(choice.value)
    if target is None:
        raise ChoiceError(f"--choose の参照先 {choice.value} が無い (参照先の ID か、http:// か https:// で始まる URL を渡す)")
    return definition_line(label, target, handwritten.path)


class _FileFixer:
    def __init__(self, handwritten: HandwrittenFile, index: Index, choices: list[Choice]):
        self.file = handwritten
        self.document = handwritten.document
        self.index = index
        self.choices = choices
        self.reports: list[Report] = []

    def report(self, line: int, column: int, message: str) -> None:
        self.reports.append(Report(self.file.path, line, column, message))

    def fix(self) -> list[str] | None:
        """直した行を返す。直すものが無ければ None。"""
        document = self.document
        lines = list(document.lines)
        # 定義の行の番号 (1 から数える) から、その行に書く内容への対応。None なら消す
        replaced: dict[int, str | None] = {}
        used_order: list[tuple[str, markdown.Reference]] = []
        seen_used: set[str] = set()
        # [ラベル][] (collapsed) も、検査 b と同じく使われているものとして数える (形の誤りは検査 b が報告する)
        for reference in document.references:
            key = markdown.normalize_label(reference.label)
            if key not in seen_used:
                seen_used.add(key)
                used_order.append((key, reference))

        images = image_only_labels(document)
        chosen: dict[str, str] = {}
        for choice in self.choices:
            key = markdown.normalize_label(choice.label)
            reference = next((r for k, r in used_order if k == key), None)
            if reference is None:
                raise ChoiceError(f"--choose のラベル {choice.label} は、{self.file.path} の本文で使われていない")
            chosen[key] = _choice_line(choice, _label_text(reference.label), self.file, self.index)

        # 同じラベルの定義の行
        first: dict[str, markdown.Definition] = {}
        for definition in document.definitions:
            key = markdown.normalize_label(definition.label)
            if key in chosen:
                # 選んだ参照先で置き換えるので、同じラベルの今の定義の行はすべて消す
                replaced[definition.line] = None
                continue
            if key not in first:
                first[key] = definition
                continue
            earlier = first[key]
            this_key = _definition_key(self.file, definition, self.index)
            if this_key is not None and this_key == _definition_key(self.file, earlier, self.index):
                replaced[definition.line] = None
            else:
                self.report(
                    definition.line, definition.column,
                    f"ラベル {definition.label} の定義の行が {earlier.line} 行目にもあり、参照先が違う"
                    f" ({strip_angle(earlier.destination)} と {strip_angle(definition.destination)})。"
                    "--choose で参照先を 1 つ選ぶ",
                )

        # title の書き換え
        for key, definition in first.items():
            if key in images or is_external(definition.destination):
                continue
            resolved = resolve(self.file, definition, self.index)
            quote = definition.quote or '"'
            if resolved.target is None:
                if resolved.by_id is not None:
                    # ID は参照先にあり、パスだけが違う。直し方は 1 つに決まる
                    replaced[definition.line] = definition_line(definition.label, resolved.by_id, self.file.path, quote)
                elif key in seen_used:
                    self.report(
                        definition.line, definition.column,
                        f"ラベル {definition.label} の定義の行の href から参照先を求められない ({resolved.message})。"
                        "--choose で参照先を渡す",
                    )
                continue
            full_name = resolved.target.full_name()
            if definition.title_text == full_name:
                continue
            line = lines[definition.line - 1]
            head = line[: definition.title_start].rstrip()
            replaced[definition.line] = f"{head} {quote}{markdown.escape_title(full_name, quote)}{markdown.closing_quote(quote)}"

        # 定義の無いラベル
        added: list[str] = []
        unresolved = False
        for key, reference in used_order:
            if key in chosen:
                added.append(chosen[key])
                continue
            if key in first:
                continue
            candidates = self.index.candidates(reference.label)
            label = _label_text(reference.label)
            if len(candidates) == 1:
                added.append(definition_line(label, candidates[0], self.file.path))
                continue
            unresolved = True
            where = (reference.label_line, reference.label_column)
            if candidates:
                self.report(
                    *where,
                    f"ラベル {label} の参照先の候補が {len(candidates)} 件ある: {candidate_text(candidates)}。--choose で選ぶ",
                )
            else:
                self.report(*where, f"ラベル {label} の参照先の候補が無い。参照先の ID か外部の URL を --choose で渡す")

        # 使われていない定義の行
        for key, definition in first.items():
            if key in seen_used or key in chosen or key in images:
                continue
            if unresolved:
                self.report(
                    definition.line, definition.column,
                    f"ラベル {definition.label} の定義の行が本文で使われていないが、定義の無いラベルが残っているので消さなかった"
                    " (ラベルの書き間違いのことがある)",
                )
            else:
                replaced[definition.line] = None

        moved = [d.line for d in document.definitions if d.in_paragraph or d.line <= document.body_end]
        needs_anchor = self.needs_file_anchor()
        if not replaced and not added and not moved and not needs_anchor:
            return None
        return self.rebuild(lines, replaced, added, needs_anchor)

    def needs_file_anchor(self) -> bool:
        """先頭の行 (空行を除く) がアンカーでなければ True。アンカーの ID が違えば、報告して False。"""
        first = self.document.first_nonblank()
        anchor = next((a for a in self.document.anchors if a.line == first), None)
        if anchor is None:
            return True
        if anchor.name != self.file.id:
            self.report(
                anchor.line, anchor.column,
                f"先頭のアンカーの ID {anchor.name} が、ファイルの ID {self.file.id} と違う。"
                "アンカーを書き換えるかどうかを決めて、手で直す",
            )
        return False

    def rebuild(self, lines: list[str], replaced: dict[int, str | None], added: list[str], needs_anchor: bool) -> list[str]:
        """本文の途中の定義の行を末尾のまとまりへ移し、末尾のまとまりを「本文 + 空行 + 定義の行」の形に組み直す
        (段落の一部になった定義の行は、前に空行が入るので、定義の行として読まれるようになる)。"""
        document = self.document
        definition_lines = document.definition_lines()
        body: list[str] = []
        moved_lines: list[str] = []
        for number in range(1, document.body_end + 1):
            line = lines[number - 1]
            if number in definition_lines:
                kept = replaced.get(number, line)
                if kept is not None:
                    moved_lines.append(kept)
                # 消した定義の行の前後が両方とも空行なら、空行を 1 つにする
                if body and not body[-1].strip() and (number == document.body_end or not lines[number].strip()):
                    body.pop()
                continue
            body.append(line)
        trailing: list[str] = []
        for number in range(document.body_end + 1, len(lines) + 1):
            line = lines[number - 1]
            if number in definition_lines:
                kept = replaced.get(number, line)
                if kept is None:
                    continue
                trailing.append(kept)
            elif trailing and trailing[-1].strip():
                trailing.append("")  # 定義の行の間の空行を 1 つだけ残す
        while trailing and not trailing[-1].strip():
            trailing.pop()
        block = moved_lines + trailing + added
        while body and not body[-1].strip():
            body.pop()
        if needs_anchor:
            start = 0
            while start < len(body) and not body[start].strip():
                start += 1
            body = [f'<a name="{self.file.id}"></a>', ""] + body[start:]
        result = body
        if block:
            result = body + [""] + block
        return result


def fix_files(root: Path, index: Index, paths: list[str] | None, choices: list[Choice]) -> FixResult:
    """paths (リポジトリのルートからの相対パス) の手書きの Markdown を直す。paths が None なら、すべての手書きの Markdown。

    --choose の値が使えなければ、何も書かずに ChoiceError を送出する。
    """
    targets = index.files if paths is None else [f for f in index.files if f.path in paths]
    for choice in choices:
        if index.file(choice.path) is None:
            raise ChoiceError(f"--choose のファイル {choice.path} は、手書きの Markdown でない")
        handwritten = index.file(choice.path)
        if handwritten not in targets:
            targets.append(handwritten)
    result = FixResult()
    outputs: dict[str, list[str]] = {}
    for handwritten in targets:
        fixer = _FileFixer(handwritten, index, [c for c in choices if c.path == handwritten.path])
        fixed = fixer.fix()
        result.reports += fixer.reports
        if fixed is not None:
            outputs[handwritten.path] = fixed
    for path, fixed in outputs.items():
        target = root / path
        raw = target.read_bytes()
        newline = "\r\n" if b"\r\n" in raw else "\n"
        bom = "﻿" if raw.startswith(b"\xef\xbb\xbf") else ""
        text = bom + newline.join(fixed) + newline
        if text.encode("utf-8") != raw:
            target.write_bytes(text.encode("utf-8"))
            result.changed.append(path)
    result.reports.sort(key=lambda r: (r.path, r.line, r.column))
    return result


def unknown_paths(index: Index, paths: list[str]) -> list[str]:
    return [p for p in paths if index.file(p) is None]

"""手書きの Markdown と、リンクの参照先の一覧。

ドメインのディレクトリの下の手書きの Markdown を見つけ、すべての Markdown (生成したファイルを含む) のアンカーから、
リンクの参照先の一覧を作る。形式の SSOT はプラグインの規則の文書 (ファイル doc-structured/rules/doc-structured-docs.md と
doc-structured/rules/doc-structured-domains.md)。要点:
  - 手書きのファイルは、ドメインのディレクトリの直下の concept.md・problem.md・design.md と、
    その種類と同じ名前のサブディレクトリの <名前>.md (子のファイル。1 階層だけ)
  - ほかの名前・場所の .md は、検査 b のエラーにする
  - 参照先のアンカーは、今のファイルの内容から読む (生成したファイルが古いことは検査 a が報告する)。YAML から決まる参照先
    (ドメイン・定義・生成したファイル) のファイルは、生成する側の対応で決め、そのファイルにアンカーがあるときだけ参照先にする
  - 参照先のラベルの候補は、ID・名前・限定付きの名前 (「種類 + 名前」に、親を直近から 0 個以上足した形)
"""

import posixpath
from dataclasses import dataclass, field
from pathlib import Path

from . import generated_header, markdown, names
from .domains import DOMAINS_DIR, Domain, Project, rel
from .generate import entry_file, file_path
from .names import Part
from .problems import Problem

README = "README.md"
# ドメインのディレクトリの直下の、生成するファイルの名前
GENERATED_NAMES = {README, *names.FILE_KINDS.values()}


@dataclass
class HandwrittenFile:
    """ドメインのディレクトリの下の、手書きのファイル。"""

    path: str  # リポジトリのルートからの相対パス
    domain: Domain
    symbol: str  # 手書きのファイルの種類の記号 (concept・problem・design)
    child: str | None  # 子のファイルなら、その名前
    document: markdown.Document

    @property
    def id(self) -> str:
        parts = [Part("d", self.domain.name), Part(self.symbol, None)]
        if self.child is not None:
            parts.append(Part(names.CHILD_FILE_SYMBOL, self.child))
        return names.build_id(parts)

    @property
    def display(self) -> str:
        """限定付きの名前に書くファイル名。子のファイルは、ドメインのディレクトリからのパス。"""
        if self.child is None:
            return names.HANDWRITTEN_FILE_KINDS[self.symbol]
        return f"{self.symbol}/{self.child}.md"

    def parts(self) -> list[str]:
        symbol = names.CHILD_FILE_SYMBOL if self.child is not None else self.symbol
        return [self.domain.full_name(), names.format_part(symbol, self.display)]

    def full_name(self) -> str:
        return names.join_parts(self.parts())


@dataclass
class Target:
    """リンクの参照先 (アンカーのある定義・ファイル・節)。"""

    id: str
    path: str  # アンカーを書いたファイルの、リポジトリのルートからの相対パス
    parts: list[str]  # ドメインから自分までの「種類 + 名前」
    name: str | None  # ラベルの候補にする名前 (日本語名・見出しの文・コードの書式のファイル名)

    def full_name(self) -> str:
        return names.join_parts(self.parts)

    def qualified_names(self) -> list[str]:
        """限定付きの名前。自分だけの「種類 + 名前」から、すべての親を書いた完全な名前まで。"""
        return [names.join_parts(self.parts[i:]) for i in range(len(self.parts) - 1, -1, -1)]

    def labels(self) -> set[str]:
        """ラベルの候補を、比べる形 (markdown.normalize_label) にしたもの。"""
        found = {self.id, *self.qualified_names()}
        if self.name:
            found.add(self.name)
        return {markdown.normalize_label(label) for label in found}

    def href(self, from_path: str) -> str:
        """from_path のファイルに書く、定義の行の href。"""
        if self.path == from_path:
            return f"#{self.id}"
        return f"{posixpath.relpath(self.path, posixpath.dirname(from_path))}#{self.id}"


@dataclass
class Index:
    files: list[HandwrittenFile] = field(default_factory=list)
    targets: dict[str, Target] = field(default_factory=dict)
    # すべての Markdown のアンカー。ID から、それを書いたファイルとアンカーへの対応 (同じ ID が 2 つあれば 2 つ)
    anchors: dict[str, list[tuple[str, markdown.Anchor]]] = field(default_factory=dict)
    documents: dict[str, markdown.Document] = field(default_factory=dict)  # パスから、読んだ Markdown への対応

    # 比べる形のラベルから、その候補の参照先への対応。最初の candidates の呼び出しで、参照先の一覧から 1 度だけ作る
    _by_label: dict[str, list[Target]] | None = field(default=None, repr=False)

    def candidates(self, label: str) -> list[Target]:
        if self._by_label is None:
            self._by_label = {}
            for target in sorted(self.targets.values(), key=lambda t: t.id):
                for key in target.labels():
                    self._by_label.setdefault(key, []).append(target)
        return list(self._by_label.get(markdown.normalize_label(label), []))

    def file(self, path: str) -> HandwrittenFile | None:
        for handwritten in self.files:
            if handwritten.path == path:
                return handwritten
        return None


def section_name(file_id: str, anchor: str) -> str | None:
    """節のアンカーの名前。file_id のファイルの節のアンカーの形 (<ファイルの ID>-h-<名前>) でなければ None。"""
    prefix = f"{file_id}-{names.SECTION.symbol}-"
    if not anchor.startswith(prefix):
        return None
    name = anchor[len(prefix) :]
    return name if names.is_name(name) else None


def read_markdown(path: Path) -> markdown.Document:
    return markdown.parse(generated_header.read_file(path).text)


class _Finder:
    def __init__(self, root: Path, project: Project):
        self.root = root
        self.project = project
        self.index = Index()
        self.problems: list[Problem] = []

    def problem(self, path: str, message: str, line: int | None = None, column: int | None = None) -> None:
        self.problems.append(Problem("b", path, message, line, column))

    def find(self) -> None:
        for domain in self.project.domains:
            self.find_in_domain(domain)
        self.read_anchors()
        self.add_targets()

    def find_in_domain(self, domain: Domain) -> None:
        directory = self.root / domain.dir
        kinds = "・".join(names.HANDWRITTEN_FILE_KINDS.values())
        # 直下のファイルを先に、同じ深さはパスの文字コードの順に
        found = sorted(directory.rglob("*.md"), key=lambda p: (len(p.relative_to(directory).parts), p.as_posix()))
        for path in found:
            relative = path.relative_to(directory)
            if any(part.startswith(".") for part in relative.parts) or not path.is_file():
                continue
            path_rel = rel(self.root, path)
            if len(relative.parts) == 1:
                if relative.name in GENERATED_NAMES:
                    continue
                symbol = relative.stem
                if symbol not in names.HANDWRITTEN_FILE_KINDS:
                    self.problem(
                        path_rel,
                        f"ドメインのディレクトリの直下に書ける手書きの Markdown は {kinds} だけ",
                    )
                    continue
                self.add_file(path, path_rel, domain, symbol, None)
                continue
            parent = relative.parts[0]
            if len(relative.parts) == 2 and parent in names.HANDWRITTEN_FILE_KINDS:
                child = relative.stem
                if not names.is_name(child):
                    self.problem(path_rel, f"子のファイルの名前 {child} が snake_case でない")
                    continue
                self.add_file(path, path_rel, domain, parent, child)
                continue
            if parent in names.HANDWRITTEN_FILE_KINDS:
                self.problem(path_rel, f"子のファイルは、ディレクトリ {parent}/ の直下にだけ書ける (サブディレクトリは 1 階層だけ)")
            else:
                directories = "・".join(f"{s}/" for s in names.HANDWRITTEN_FILE_KINDS)
                self.problem(
                    path_rel,
                    f"ドメインのサブディレクトリに書ける手書きの Markdown は、ディレクトリ {directories} の直下の子のファイルだけ",
                )

    def add_file(self, path: Path, path_rel: str, domain: Domain, symbol: str, child: str | None) -> None:
        document = read_markdown(path)
        self.index.documents[path_rel] = document
        self.index.files.append(HandwrittenFile(path_rel, domain, symbol, child, document))

    def read_anchors(self) -> None:
        domains_dir = self.root / DOMAINS_DIR
        if not domains_dir.is_dir():
            return
        for path in sorted(domains_dir.rglob("*.md")):
            relative = path.relative_to(domains_dir)
            if any(part.startswith(".") for part in relative.parts) or not path.is_file():
                continue
            path_rel = rel(self.root, path)
            document = self.index.documents.get(path_rel)
            if document is None:
                document = read_markdown(path)
                self.index.documents[path_rel] = document
            for anchor in document.anchors:
                self.index.anchors.setdefault(anchor.name, []).append((path_rel, anchor))

    def add_target(self, target_id: str, parts: list[str], name: str | None, path: str) -> None:
        """path のファイルに target_id のアンカーがあれば、参照先にする。"""
        if any(found == path for found, _ in self.index.anchors.get(target_id, [])):
            self.index.targets[target_id] = Target(target_id, path, parts, name)

    def add_targets(self) -> None:
        for domain in self.project.domains:
            # ファイルは、生成する側 (モジュール generate) の対応で決める
            self.add_target(domain.id, [domain.full_name()], None, f"{domain.dir}/{README}")
            for symbol, file_name in names.FILE_KINDS.items():
                file_id = names.build_id([Part("d", domain.name), Part(symbol, None)])
                parts = [domain.full_name(), names.format_part(symbol, file_name)]
                self.add_target(file_id, parts, f"`{file_name}`", file_path(domain, symbol))
            for entry in domain.entries():
                parts = [domain.full_name()] + [names.format_part(e.symbol, e.name_ja) for e in entry.lineage()]
                self.add_target(entry.id, parts, entry.name_ja, entry_file(entry))
        for handwritten in self.index.files:
            document = handwritten.document
            first = document.first_nonblank()
            file_anchor = next((a for a in document.anchors if a.line == first), None)
            if file_anchor is not None and file_anchor.name == handwritten.id:
                self.add_target(handwritten.id, handwritten.parts(), f"`{handwritten.display}`", handwritten.path)
            for anchor in document.anchors:
                if section_name(handwritten.id, anchor.name) is None:
                    continue
                following = document.next_nonblank(anchor.line)
                heading = document.heading_at(following) if following else None
                if heading is None or not heading.atx or heading.level < 2:
                    continue
                parts = handwritten.parts() + [names.format_part(names.SECTION.symbol, heading.text)]
                self.add_target(anchor.name, parts, heading.text, handwritten.path)


def load_documents(root: Path, project: Project) -> tuple[Index, list[Problem]]:
    """手書きの Markdown を見つけ、参照先の一覧を作る。受け付けない名前と場所の Markdown は、検査 b の問題として返す。"""
    finder = _Finder(root, project)
    finder.find()
    return finder.index, finder.problems

